<?php
require_once __DIR__ . '/../app/report-service.php';
$restaurantId = (int)$context['restaurant_id'];
$rangeError = null;
try {
    $range = inventory_report_period($_GET);
} catch (InvalidArgumentException $exception) {
    $rangeError = $exception->getMessage();
    $range = inventory_report_period(['period' => 'month']);
}
$report = inventory_profit_report($db, $restaurantId, $range['from_utc'], $range['to_utc']);
$rankings = inventory_current_food_cost_rankings($db, $restaurantId);
$highestProfit = $rankings;
usort($highestProfit, static fn(array $a, array $b): int => ($b['gross_profit'] ?? -INF) <=> ($a['gross_profit'] ?? -INF));
$lowestMargin = $rankings;
usort($lowestMargin, static fn(array $a, array $b): int => ($a['gross_margin_percent'] ?? INF) <=> ($b['gross_margin_percent'] ?? INF));
$reportValue = static fn(?float $value): string => $value === null ? 'Not available' : inv_money($value);
?>
<div class="page-heading"><div><p class="eyebrow">SALES, COSTS &amp; STOCK</p><h2>Profit Reports</h2><p>Restaurant sales are based on fully paid POS invoices. Subscription payments and unpaid/partial invoices are excluded.</p></div></div>
<?php if ($rangeError): ?><div class="notice notice-error" role="alert"><?= inv_e($rangeError) ?> Showing this month instead.</div><?php endif; ?>
<section class="panel-card report-filter"><form method="get" action="<?= inv_e(inv_base_path()) ?>/index.php" class="report-filter-form">
    <input type="hidden" name="page" value="profit-reports"><label>Period<select name="period" data-report-period><option value="today"<?= $range['period']==='today'?' selected':'' ?>>Today</option><option value="yesterday"<?= $range['period']==='yesterday'?' selected':'' ?>>Yesterday</option><option value="week"<?= $range['period']==='week'?' selected':'' ?>>This week</option><option value="month"<?= $range['period']==='month'?' selected':'' ?>>This month</option><option value="custom"<?= $range['period']==='custom'?' selected':'' ?>>Custom range</option></select></label>
    <label>From<input type="date" name="from" value="<?= inv_e($range['from_local']) ?>"></label><label>To<input type="date" name="to" value="<?= inv_e($range['to_local']) ?>"></label><button class="button button-primary" type="submit">Apply</button>
</form><p class="muted">Showing <?= inv_e($range['label']) ?> in Asia/Colombo time.</p></section>
<div class="report-metric-grid">
    <article class="metric-card"><p>Paid Food Sales</p><strong><?= inv_e(inv_money($report['sales_revenue'])) ?></strong><small>Subtotal less invoice discount</small></article>
    <article class="metric-card"><p>Tracked Ingredient Cost</p><strong><?= inv_e($reportValue($report['worker_initialized'] && $report['paid_invoice_count'] > 0 && $report['incomplete_invoice_count']===0?$report['tracked_cogs']:null)) ?></strong><small>Processed KOT consumption less tracked returns</small></article>
    <article class="metric-card"><p>Gross Profit</p><strong><?= inv_e($reportValue($report['gross_profit'])) ?></strong><small>Not net profit; excludes operating expenses</small></article>
    <article class="metric-card"><p>Gross Margin</p><strong><?= $report['gross_margin_percent']===null?'Not available':inv_e(number_format($report['gross_margin_percent'],2).'%') ?></strong><small>Gross profit divided by paid food sales</small></article>
    <article class="metric-card"><p>Wastage Cost</p><strong><?= inv_e(inv_money($report['wastage_total'])) ?></strong><small>Reported separately; not subtracted a second time</small></article>
    <article class="metric-card"><p>Current Stock Value</p><strong><?= inv_e(inv_money($report['stock_value'])) ?></strong><small>Current quantity at weighted-average cost</small></article>
</div>
<?php if ($report['incomplete_invoice_count']>0): ?><div class="notice notice-warning" role="status">Gross profit is withheld because <?= (int)$report['incomplete_invoice_count'] ?> of <?= (int)$report['paid_invoice_count'] ?> fully paid invoice(s) have KOT records that are missing, unprocessed, unresolved, unmapped, or not fully matched to order quantities. Resolve the KOT/recipe issues and rerun the worker before relying on gross profit.</div><?php endif; ?>
<?php if (!$report['worker_initialized']): ?><div class="notice notice-warning" role="status">Gross profit is unavailable because the KOT stock worker has not been initialized. No automatic stock consumption is running.</div><?php endif; ?>
<div class="notice notice-info" role="note">Revenue semantics: paid POS invoice subtotal less discount. Service charge, tax, delivery charges, packaging charges, and tips are displayed separately or excluded from food sales. KOT cancellation classified as wastage remains part of material consumption cost; the separate wastage figure is a breakdown and must not be deducted twice. No salary, rent, utilities, or other operating-expense data is included.</div>
<div class="two-column-grid report-grid">
    <section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">TENDER RECEIPTS</p><h3>Payments by method</h3></div></div><?php if (!$report['payment_rows']): ?><p class="empty-state">No POS payment records were recorded in this period.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Method</th><th>Payment records</th><th>Amount received</th></tr></thead><tbody><?php foreach ($report['payment_rows'] as $row): ?><tr><td><?= inv_e(str_replace('_',' ',$row['method'])) ?></td><td><?= (int)$row['payment_count'] ?></td><td><?= inv_e(inv_money($row['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="muted">Uses POS payment records by payment timestamp. It does not include subscription payments.</p></section>
    <section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">RECEIVED STOCK</p><h3>Purchases by supplier / material</h3></div></div><?php if (!$report['purchase_rows']): ?><p class="empty-state">No received stock purchases were recorded in this period.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Supplier</th><th>Material</th><th>Quantity</th><th>Purchase cost</th></tr></thead><tbody><?php foreach ($report['purchase_rows'] as $row): ?><tr><td><?= inv_e($row['supplier_name']) ?></td><td><?= inv_e($row['material_name']) ?></td><td><?= inv_e(inv_decimal($row['quantity'],4).' '.$row['base_unit']) ?></td><td><?= inv_e(inv_money($row['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
    <section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">RECORDED LOSS</p><h3>Wastage by reason</h3></div></div><?php if (!$report['wastage_reason_rows']): ?><p class="empty-state">No wastage records were posted in this period.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Reason</th><th>Records</th><th>Recorded cost</th><th>Unmatched count</th></tr></thead><tbody><?php foreach ($report['wastage_reason_rows'] as $row): ?><tr><td><?= inv_e(str_replace('_',' ',$row['reason_code'])) ?></td><td><?= (int)$row['record_count'] ?></td><td><?= inv_e(inv_money($row['amount'])) ?></td><td><?= inv_e(inv_decimal($row['unmatched_quantity'],2)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
    <section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">TOP MATERIAL LOSSES</p><h3>Wastage by material</h3></div></div><?php if (!$report['wastage_material_rows']): ?><p class="empty-state">No material-level wastage entries were recorded in this period.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Material</th><th>Quantity</th><th>Recorded cost</th></tr></thead><tbody><?php foreach ($report['wastage_material_rows'] as $row): ?><tr><td><?= inv_e($row['name']) ?></td><td><?= inv_e(inv_decimal($row['quantity'],4).' '.$row['base_unit']) ?></td><td><?= inv_e(inv_money($row['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div>
<div class="two-column-grid report-grid">
    <section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">CURRENT RECIPE ESTIMATES</p><h3>Highest gross-profit menu mappings</h3></div></div><?php if (!$highestProfit): ?><p class="empty-state">No complete recipes with known material costs are available.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Menu mapping</th><th>Selling price</th><th>Ingredient cost</th><th>Gross profit</th></tr></thead><tbody><?php foreach (array_slice($highestProfit,0,5) as $row): ?><tr><td><?= inv_e($row['name'].' · '.$row['mapping']) ?></td><td><?= inv_e(inv_money($row['selling_price'])) ?></td><td><?= inv_e(inv_money($row['ingredient_cost'])) ?></td><td><?= inv_e(inv_money($row['gross_profit'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><a class="button button-small button-quiet" href="<?= inv_e(inv_route('food-costing')) ?>">Open Food Costing</a></section>
    <section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">CURRENT RECIPE ESTIMATES</p><h3>Lowest gross-margin menu mappings</h3></div></div><?php if (!$lowestMargin): ?><p class="empty-state">No complete recipes with known material costs are available.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Menu mapping</th><th>Selling price</th><th>Ingredient cost</th><th>Gross margin</th></tr></thead><tbody><?php foreach (array_slice($lowestMargin,0,5) as $row): ?><tr><td><?= inv_e($row['name'].' · '.$row['mapping']) ?></td><td><?= inv_e(inv_money($row['selling_price'])) ?></td><td><?= inv_e(inv_money($row['ingredient_cost'])) ?></td><td><?= $row['gross_margin_percent']===null?'—':inv_e(number_format($row['gross_margin_percent'],2).'%') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div>
<section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">WEIGHTED AVERAGE COST TREND</p><h3>Material cost history</h3></div></div><?php if (!$report['cost_trend_rows']): ?><p class="empty-state">No stock-cost movements were recorded in this period.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Date/time (UTC)</th><th>Material</th><th>Movement</th><th>Quantity change</th><th>Movement unit cost</th><th>Average cost after movement</th></tr></thead><tbody><?php foreach ($report['cost_trend_rows'] as $row): ?><tr><td><?= inv_e($row['effective_at']) ?></td><td><?= inv_e($row['material_name']) ?></td><td><?= inv_e($row['movement_type']) ?></td><td><?= inv_e(inv_decimal($row['quantity_base'],4).' '.$row['base_unit']) ?></td><td><?= inv_e(inv_money($row['unit_cost'])) ?></td><td><?= $row['average_cost_after']===null?'Not available at zero/negative stock':inv_e(inv_money($row['average_cost_after']).' / '.$row['base_unit']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel-card data-panel"><div class="panel-title"><div><p class="eyebrow">PAID POS INVOICES</p><h3>Invoice-level food sales and tracked cost</h3></div></div><?php if (!$report['invoice_rows']): ?><p class="empty-state">No fully paid POS invoices in this period.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Invoice / order</th><th>Created (UTC)</th><th>Food revenue</th><th>Tracked ingredient cost</th><th>Included fees (not food revenue)</th><th>Cost status</th></tr></thead><tbody><?php foreach ($report['invoice_rows'] as $row): ?><tr><td>#<?= (int)$row['invoice_id'] ?> / #<?= (int)$row['order_id'] ?></td><td><?= inv_e($row['created_at']) ?></td><td><?= inv_e(inv_money($row['revenue'])) ?></td><td><?= $row['cogs']===null?'—':inv_e(inv_money($row['cogs'])) ?></td><td><?= inv_e('Service '.inv_money($row['service_charge']).' · Tax '.inv_money($row['tax']).' · Delivery '.inv_money($row['delivery_charge']).' · Packaging '.inv_money($row['packaging_charge'])) ?></td><td><span class="status-pill<?= $row['complete']?'':' status-off' ?>"><?= $row['complete']?'Complete':'Incomplete' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
